#include <iostream>
#include <string>
#include <sstream>

std::string markdownToHtml(const std::string& markdown) {
    std::string html;
    std::stringstream ss(markdown);
    ss >> html;
    return html;
}

int main() {
    std::string markdown = "# Hello World\n\nThis is a markdown example.\n\n*";
    std::string html = markdownToHtml(markdown);
    std::cout << "MD: " << markdown << std::endl;
    std::cout << "HTML: " << html << std::endl;
    return 0;
}
```

